class Solution {
  public long minOperations(int[][] queries) {
    long ans = 0;
    for (int[] q : queries) {
      long steps = 0;
      long lo = 1;
      for (int t = 1; lo <= q[1]; t++) {
        long hi = lo * 4 - 1;
        long a = Math.max(lo, q[0]), b = Math.min(hi, q[1]);
        if (a <= b) steps += (b - a + 1) * t;
        lo *= 4;
      }
      ans += (steps + 1) / 2;
    }
    return ans;
  }
}
